// Build a Markdown brief from the sources that survived the filter.
// Everything here is plain string work - no credential, no request.
//
// Field names come from the DuckDuckGo node's page-metadata output, which
// prefixes them: pageContent, pageSiteName, pagePublished.

const sources = $input.first().json.data || [];
const query = $('Search and extract article text').params.query || 'the search query';

const lines = [
  '# Research brief',
  '',
  `**Question:** ${query}`,
  `**Sources:** ${sources.length}`,
  `**Built:** ${new Date().toISOString().slice(0, 10)}`,
  '',
];

sources.forEach((s, i) => {
  const site = s.pageSiteName || s.hostname || '';
  const date = s.pagePublished ? ` · ${String(s.pagePublished).slice(0, 10)}` : '';
  const full = String(s.pageContent || '').replace(/\s+/g, ' ').trim();
  const extract = full.slice(0, 700);

  lines.push(`## ${i + 1}. ${s.title || 'Untitled'}`);
  lines.push(`${site}${date}`);
  lines.push('');
  lines.push(`> ${extract}${full.length > 700 ? '…' : ''}`);
  lines.push('');
  lines.push(`[Read in full](${s.url})`);
  lines.push('');
});

return [{ json: { query, sourceCount: sources.length, brief: lines.join('\n') } }];
